/**
 * 7-bag randomizer: infinite generator, each block of 7 draws
 * contains every tetromino exactly once.
 */
export function createBag(rng: Rng): {
  next(): IteratorResult<PieceKind>
  [Symbol.iterator](): IterableIterator<PieceKind>
} {
  let bag: PieceKind[] = []
  return {
    next(): IteratorResult<PieceKind> {
      if (bag.length === 0) bag = shuffle(PIECE_KINDS.slice(), rng)
      return { done: false, value: bag.pop()! }
    },
  }
}

export function drawFromBag(bag: Iterator<PieceKind>, count: number): PieceKind[] {
  return Array.from({ length: count }, () => bag.next().value!)
}

