import { action, wrap, sleep, withAbort } from '@reatom/core'
import { isGrounded } from '../game/board'
import type { Tetris } from './tetris'

const LOCK_DELAY_MS = 500
const MAX_LOCK_RESETS = 15

/** Gravity + lock-delay effects, owned by `tetrisLoop.startLoop`. */
export function createLoop(game: Tetris) {
  const gravity = action(async () => {
    while (true) {
      await wrap(sleep(game.gravityMs()))
      game.tick()
    }
  }, 'tetrisLoop._gravity').extend(withAbort('manual'))

  const lockDelay = action(async () => {
    while (true) {
      await wrap(sleep(50))
      if (game.status() !== 'running') continue
      const piece = game.active()
      if (piece === null) continue
      if (!isGrounded(game.board(), piece)) continue
      // grounded: start (or re-arm) the lock delay window
      await wrap(sleep(LOCK_DELAY_MS))
      if (game.status() !== 'running') continue
      const still = game.active()
      if (still === null) continue
      if (!isGrounded(game.board(), still)) continue
      if (game.lockDelayResets() >= MAX_LOCK_RESETS) {
        game.lock()
      } else {
        game.bumpLockDelay()
        game.lock()
      }
    }
  }, 'tetrisLoop._lockDelay').extend(withAbort('manual'))

  const startLoop = action(() => {
    gravity()
    lockDelay()
  }, 'tetrisLoop.startLoop')

  const stopLoop = action(() => {
    gravity.abort()
    lockDelay.abort()
  }, 'tetrisLoop.stopLoop')

  return { gravity, lockDelay, startLoop, stopLoop }
}

